class Wizard {
  constructor(name, initialMana) {
    this.name = name;
    // TODO: Make 'mana' a private field using '#' syntax
    this.mana = initialMana;
  }

  castSpell(spellName, spellCost) {
    // TODO: Access the private mana field here
    if (this.mana >= spellCost) {
      this.mana -= spellCost;
      return `${this.name} casts ${spellName} and has ${this.mana} mana left.`;
    } else {
      return `${this.name} doesn't have enough mana to cast ${spellName}!`;
    }
  }

  rechargeMana(amount) {
    // TODO: Access the private mana field here
    this.mana += amount;
    return `${this.name} recharges and now has ${this.mana} mana.`;
  }

  getMana() {
    // TODO: Return the private mana field here
    return this.mana;
  }
}

